import xml.etree.ElementTree as ET

# Parse stretch.xml inline from the content we read
xml_content = open("/Users/wangyifan/Projects/auto_adapter2.0/AA1/assets/mjcf/hello_robot_stretch_2/stretch.xml").read()
root = ET.fromstring(xml_content)

# ── Collect defaults (class → joint/actuator attrs) ──────────────────────────
defaults = {}  # class_name -> {tag -> attrib_dict}

def collect_defaults(node, parent_class=None):
    for child in node:
        if child.tag == "default":
            cls = child.get("class", parent_class)
            if cls not in defaults:
                defaults[cls] = {}
            for sub in child:
                if sub.tag not in defaults[cls]:
                    defaults[cls][sub.tag] = {}
                defaults[cls][sub.tag].update(sub.attrib)
            collect_defaults(child, cls)

for d in root.iter("default"):
    collect_defaults(d)

print("Default classes found:", list(defaults.keys()))
for cls, tags in defaults.items():
    print(f"  {cls}: {list(tags.keys())}")

# ── Build default class lookup ────────────────────────────────────────────────
# We'll store per-class defaults for joint and actuator tags
class_defaults = {}  # class_name -> {element_tag -> {attr -> val}}

def parse_defaults(node, inherited_class=None):
    for child in node:
        if child.tag != "default":
            continue
        cls = child.get("class", inherited_class)
        if cls not in class_defaults:
            class_defaults[cls] = {}
        for sub in child:
            if sub.tag == "default":
                continue
            if sub.tag not in class_defaults[cls]:
                class_defaults[cls][sub.tag] = {}
            class_defaults[cls][sub.tag].update(sub.attrib)
        parse_defaults(child, cls)

for d_node in root.findall("default"):
    parse_defaults(d_node)

print("Classes:", list(class_defaults.keys()))
for cls, tags in class_defaults.items():
    for tag, attrs in tags.items():
        print(f"  [{cls}] <{tag}>: {attrs}")

